-- Table structure for employment_history
DROP TABLE IF EXISTS `employment_history`;
CREATE TABLE `employment_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `employee_id` int NOT NULL,
  `change_type` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `old_value` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `new_value` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `effective_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `employment_history_ibfk_1` (`employee_id`),
  CONSTRAINT `employment_history_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

