-- Table structure for oauth_integrations
DROP TABLE IF EXISTS `oauth_integrations`;
CREATE TABLE `oauth_integrations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `provider` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `access_token` text COLLATE utf8mb4_general_ci,
  `refresh_token` text COLLATE utf8mb4_general_ci,
  `token_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'Bearer',
  `scope` text COLLATE utf8mb4_general_ci,
  `expires_at` datetime DEFAULT NULL,
  `member_urn` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `organization_urn` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `account_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'NOT_CONNECTED',
  `connected_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `provider` (`provider`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for offer_letters
DROP TABLE IF EXISTS `offer_letters`;
CREATE TABLE `offer_letters` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `candidate_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `job_position` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `department_id` int NOT NULL,
  `salary_offered` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `joining_date` date NOT NULL,
  `reporting_manager` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `employment_type` enum('Full-time','Part-time','Contract') COLLATE utf8mb4_general_ci DEFAULT 'Full-time',
  `offer_expiry_date` date NOT NULL,
  `notes` text COLLATE utf8mb4_general_ci,
  `status` enum('Pending','Accepted','Rejected') COLLATE utf8mb4_general_ci DEFAULT 'Pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `candidate_id` int DEFAULT NULL,
  `template_id` int DEFAULT NULL,
  `template_snapshot` longtext COLLATE utf8mb4_general_ci,
  `offer_date` date DEFAULT NULL,
  PRIMARY KEY (`id`)
