-- Table structure for roles
DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `role_key` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `role_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci,
  `is_system` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for salary_components
DROP TABLE IF EXISTS `salary_components`;
CREATE TABLE `salary_components` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `type` enum('Earning','Deduction','Contribution') COLLATE utf8mb4_general_ci NOT NULL,
  `taxable` enum('Yes','No','Partial') COLLATE utf8mb4_general_ci DEFAULT 'Yes',
  `formula` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '',
  `frequency` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'Monthly',
  `status` enum('Active','Inactive') COLLATE utf8mb4_general_ci DEFAULT 'Active',
  `calc_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'fixed',
  `percentage_value` decimal(6,2) DEFAULT '0.00',
  `percentage_basis` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'basic',
  `default_amount` decimal(12,2) DEFAULT '0.00',
  `is_statutory` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

