-- Table structure for salary_structure_components
DROP TABLE IF EXISTS `salary_structure_components`;
CREATE TABLE `salary_structure_components` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `structure_id` int NOT NULL,
