-- Table structure for sales_enquiries
DROP TABLE IF EXISTS `sales_enquiries`;
CREATE TABLE `sales_enquiries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `contact_email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_phone` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `enquiry_details` text COLLATE utf8mb4_general_ci,
  `status` enum('new','contacted','qualified','proposal_sent','won','lost') COLLATE utf8mb4_general_ci DEFAULT 'new',
  `assigned_to` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for sales_entries
DROP TABLE IF EXISTS `sales_entries`;
CREATE TABLE `sales_entries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `enquiry_id` int DEFAULT NULL,
  `amount` decimal(10,2) NOT NULL,
  `sale_date` date DEFAULT NULL,
  `notes` text COLLATE utf8mb4_general_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `enquiry_id` (`enquiry_id`),
  CONSTRAINT `sales_entries_ibfk_1` FOREIGN KEY (`enquiry_id`) REFERENCES `sales_enquiries` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for sales_followups
DROP TABLE IF EXISTS `sales_followups`;
CREATE TABLE `sales_followups` (
  `id` int NOT NULL AUTO_INCREMENT,
  `enquiry_id` int DEFAULT NULL,
  `followup_date` date DEFAULT NULL,
  `notes` text COLLATE utf8mb4_general_ci,
  `next_action` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('pending','completed') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `enquiry_id` (`enquiry_id`),
  CONSTRAINT `sales_followups_ibfk_1` FOREIGN KEY (`enquiry_id`) REFERENCES `sales_enquiries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for shift_roster
DROP TABLE IF EXISTS `shift_roster`;
CREATE TABLE `shift_roster` (
  `id` int NOT NULL AUTO_INCREMENT,
  `employee_id` int NOT NULL,
  `shift_id` int NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for shifts
DROP TABLE IF EXISTS `shifts`;
CREATE TABLE `shifts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `startTime` varchar(50) DEFAULT '09:00 AM',
  `endTime` varchar(50) DEFAULT '06:00 PM',
  `breakTime` varchar(50) DEFAULT '60 mins',
  `graceTime` varchar(50) DEFAULT '15 mins',
  `workingHours` varchar(50) DEFAULT '9 hours',
  `employees` int DEFAULT '0',
  `status` varchar(20) DEFAULT 'Active',
  `description` text,
  `createdDate` varchar(50) DEFAULT '01 Jan 2026',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for sprints
DROP TABLE IF EXISTS `sprints`;
CREATE TABLE `sprints` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `goal` text COLLATE utf8mb4_general_ci,
  `project_id` int DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `status` varchar(30) COLLATE utf8mb4_general_ci DEFAULT 'Planning',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
